BEGIN; INSERT INTO clinics(id,name,clerk_org_id) VALUES('ci-e22-a','CI E22 A','ci_e22_org_a'),('ci-e22-b','CI E22 B','ci_e22_org_b') ON CONFLICT(id) DO NOTHING; INSERT INTO compliance_controls(id,clinic_id,framework,control_key,title,status) VALUES('ci-e22-control-a','ci-e22-a','HIPAA-Security','164.312-a','Access control','evidenced') ON CONFLICT(id) DO NOTHING; SET ROLE authenticated; SELECT set_config('app.clerk_org_id','ci_e22_org_a',false); DO 'BEGIN IF NOT EXISTS(SELECT 1 FROM compliance_controls WHERE id=''ci-e22-control-a'') THEN RAISE EXCEPTION ''tenant A cannot read control''; END IF; END'; SELECT set_config('app.clerk_org_id','ci_e22_org_b',false); DO 'BEGIN IF EXISTS(SELECT 1 FROM compliance_controls WHERE id=''ci-e22-control-a'') THEN RAISE EXCEPTION ''cross-tenant compliance read''; END IF; END'; RESET ROLE; ROLLBACK;